-- script: main
-- velox:lock-timeout 5s

-- review: add-identity: adds an identity to column users.id and sets its counter past the column's largest value; serial-to-identity: turns serial column users.id into an identity: its default and sequence are dropped
ALTER TABLE "users" ALTER COLUMN "id" DROP DEFAULT;
DROP SEQUENCE "users_id_seq";
ALTER TABLE "users" ALTER COLUMN "id" ADD GENERATED BY DEFAULT AS IDENTITY (SEQUENCE NAME "users_id_seq");
SELECT setval(pg_get_serial_sequence('"users"', 'id'), coalesce(max("id"), 0) + 1, false) FROM "users";
